import{_ as o,I as n,c as r,o as e,a3 as a,b as s,w as l,a as d,J as E,a4 as c}from"./chunks/framework.BusRvirq.js";const D=JSON.parse('{"title":"[특허 백서] 명세 기반 4단계 위저드 및 빌드 자가치유 시스템","description":"AI 코딩 에이전트의 환각을 방지하는 4단계 명세 위저드와 컴파일러 에러 역피드백 기반 빌드 자가치유 기술 백서","frontmatter":{"title":"[특허 백서] 명세 기반 4단계 위저드 및 빌드 자가치유 시스템","shortTitle":"[07호] 4단계 위저드 & 빌드 치유","category":"원천기술 & 특허","sort":3,"description":"AI 코딩 에이전트의 환각을 방지하는 4단계 명세 위저드와 컴파일러 에러 역피드백 기반 빌드 자가치유 기술 백서","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/patents/07-four-stage-wizard-build.html"}]]},"headers":[],"relativePath":"patents/07-four-stage-wizard-build.md","filePath":"ko/patents/07-four-stage-wizard-build.md","lastUpdated":1791239682000}'),B={name:"patents/07-four-stage-wizard-build.md"};function C(A,t,g,f,p,h){const i=n("Mermaid");return e(),r("div",null,[t[1]||(t[1]=a('<h1 id="명세-기반-4단계-위저드-및-빌드-자가치유-시스템" tabindex="-1">명세 기반 4단계 위저드 및 빌드 자가치유 시스템 <a class="header-anchor" href="#명세-기반-4단계-위저드-및-빌드-자가치유-시스템" aria-label="Permalink to “명세 기반 4단계 위저드 및 빌드 자가치유 시스템”">​</a></h1><blockquote><p><strong>특허 출원 관리 번호</strong>: 제07호<br><strong>발명의 명칭</strong>: 명세 기반 4단계 위저드 및 빌드 아티팩트 검증 피드백 루프를 이용한 소스코드 자율 변이 및 자가 치유(Self-Healing) 시스템 및 방법<br><strong>출원 관리 상태</strong>: 출원 준비 (우선심사 대상, 등록가능성 A등급 평가)<br><strong>연계 프로덕트</strong>: <code>SyncBoot</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-해결하려는-기술적-과제" tabindex="-1">1. 해결하려는 기술적 과제 <a class="header-anchor" href="#_1-해결하려는-기술적-과제" aria-label="Permalink to “1. 해결하려는 기술적 과제”">​</a></h2><p>대규모 언어 모델(LLM) 기반의 코딩 도구(예: GitHub Copilot, 일반 AI 코딩 어시스턴트)는 자연어 프롬프트를 바탕으로 소스코드를 빠르게 작성하지만, 기존 코드베이스의 전체 문맥과 의존성 관계를 완전하게 파악하지 못하는 한계가 있습니다.</p><p>이로 인해 다음과 같은 심각한 소프트웨어 공학 결함이 발생합니다:</p><ol><li><strong>환각 기반 코드 생성</strong>: 실제 존재하지 않는 서드파티 패키지나 클래스 메서드를 임의로 호출하여 컴파일 오류를 유발.</li><li><strong>가짜 정상(Fake Fallback) 코드 커밋</strong>: 비즈니스 로직을 온전히 구현하지 않고 빈 껍데기 메서드(<code>return null;</code> 등)를 생성하여 단위 테스트를 기만.</li><li><strong>빌드 실패 아티팩트 방치</strong>: 패치 적용 후 컴파일 오류나 테스트 실패가 발생해도 이를 감지하지 못하고 그대로 커밋하여 CI/CD 파이프라인을 마비.</li></ol>',7)),(e(),s(c,null,{default:l(()=>[E(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22%EC%9E%90%EC%97%B0%EC%96%B4%20%EC%9A%94%EA%B5%AC%EC%82%AC%ED%95%AD%20%EC%9E%85%EB%A0%A5%22%5D%20--%3E%20S1%5B%22Step%201%3A%20%EC%BD%94%EB%93%9C%EB%B2%A0%EC%9D%B4%EC%8A%A4%20%EC%8B%A4%EC%B8%A1%20%EB%B0%8F%20%EC%A2%85%EC%86%8D%EC%84%B1%20%EB%B6%84%EC%84%9D%22%5D%0A%20%20%20%20S1%20--%3E%20S2%5B%22Step%202%3A%20%EA%B8%B0%EB%8A%A5%20%EB%AA%85%EC%84%B8%20%EB%B0%8F%20%EC%97%94%EB%93%9C%ED%8F%AC%EC%9D%B8%ED%8A%B8%20%EC%A0%95%EC%9D%98%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22Step%203%3A%20DDL%20%EC%8A%A4%ED%82%A4%EB%A7%88%20%26%20focusFiles%20%EA%B2%A9%EB%A6%AC%20%EA%B3%84%ED%9A%8D%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22Step%204%3A%20AtomicDiffPatchEngine%20%EC%86%8C%EC%8A%A4%20%EB%B3%80%EC%9D%B4%22%5D%0A%20%20%20%20S4%20--%3E%20Build%7B%22%EC%8B%A4%EC%A0%9C%20%EB%B0%B1%EC%97%94%EB%93%9C%20%EB%B9%8C%EB%93%9C%20%EB%B0%8F%20%EB%8B%A8%EC%9C%84%20%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EA%B2%80%EC%A6%9D%22%7D%0A%20%20%20%20Build%20--%20%22%EB%B9%8C%EB%93%9C%20%EC%84%B1%EA%B3%B5%20(Pass)%22%20--%3E%20PR%5B%22%EA%B2%80%EC%A6%9D%20%EC%99%84%EB%A3%8C%20PR%20%EC%9E%90%EB%8F%99%20%EB%B0%9C%EA%B8%89%22%5D%0A%20%20%20%20Build%20--%20%22%EC%BB%B4%ED%8C%8C%EC%9D%BC%2F%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EC%8B%A4%ED%8C%A8%22%20--%3E%20Feedback%5B%22%EC%BB%B4%ED%8C%8C%EC%9D%BC%EB%9F%AC%20%EC%98%A4%EB%A5%98%20%EB%A1%9C%EA%B7%B8%20%26%20%EC%8B%A4%ED%8C%A8%20%EC%A7%80%EC%A0%90%20%EC%86%8C%EC%8A%A4%20%EC%B6%94%EC%B6%9C%22%5D%0A%20%20%20%20Feedback%20--%3E%20Repair%5B%22%EC%9E%90%EA%B0%80%EC%B9%98%EC%9C%A0%20%EB%A3%A8%ED%94%84%20(autoRepairCode)%22%5D%0A%20%20%20%20Repair%20--%3E%20%7C%EC%B5%9C%EB%8C%80%203~5%ED%9A%8C%20%EB%B0%98%EB%B3%B5%7C%20S4%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_2-4단계-명세-위저드-파이프라인" tabindex="-1">2. 4단계 명세 위저드 파이프라인 <a class="header-anchor" href="#_2-4단계-명세-위저드-파이프라인" aria-label="Permalink to “2. 4단계 명세 위저드 파이프라인”">​</a></h2><p>본 발명은 자연어 지시를 즉시 코드로 변환하지 않고, 4단계의 점진적 위저드 파이프라인을 거치도록 강제하여 환각 발생 가능성을 구조적으로 억제합니다.</p><h3 id="step-1-코드베이스-실측-grounding-analysis" tabindex="-1">Step 1: 코드베이스 실측 (Grounding Analysis) <a class="header-anchor" href="#step-1-코드베이스-실측-grounding-analysis" aria-label="Permalink to “Step 1: 코드베이스 실측 (Grounding Analysis)”">​</a></h3><ul><li>현재 리포지토리의 소스코드 트리, Maven/Gradle 종속성 라이브러리 목록, 기정의된 엔티티 및 DTO 스키마를 정적 분석합니다.</li><li>변경 작업에 필요한 프로젝트 컨텍스트(사용 중인 Spring Boot 버전, 의존성 라이브러리 버전 등)를 객관적 데이터로 확보합니다.</li></ul><h3 id="step-2-기능-및-화면-명세-도출-specification-definition" tabindex="-1">Step 2: 기능 및 화면 명세 도출 (Specification Definition) <a class="header-anchor" href="#step-2-기능-및-화면-명세-도출-specification-definition" aria-label="Permalink to “Step 2: 기능 및 화면 명세 도출 (Specification Definition)”">​</a></h3><ul><li>사용자의 요구사항을 비즈니스 규칙, 입력 검증 조건, 인가 권한 요구사항으로 세분화합니다.</li><li>구현될 RESTful API 명세(엔드포인트 URI, HTTP Method, Request/Response JSON 스키마)를 선언적 문서 형태로 먼저 확정합니다.</li></ul><h3 id="step-3-ddl-스키마-및-focusfiles-계획-수립-plan-scope-isolation" tabindex="-1">Step 3: DDL 스키마 및 focusFiles 계획 수립 (Plan &amp; Scope Isolation) <a class="header-anchor" href="#step-3-ddl-스키마-및-focusfiles-계획-수립-plan-scope-isolation" aria-label="Permalink to “Step 3: DDL 스키마 및 focusFiles 계획 수립 (Plan &amp; Scope Isolation)”">​</a></h3><ul><li>변경 대상 데이터베이스 DDL 스크립트를 작성합니다.</li><li>전체 리포지토리 중 실제로 수정이 필요한 파일 목록을 <code>focusFiles</code> 배열로 엄격히 한정하여, 불필요한 전역 소스코드 오염을 방지합니다.</li></ul><h3 id="step-4-원자적-diff-패치-적용-atomic-code-mutation" tabindex="-1">Step 4: 원자적 Diff 패치 적용 (Atomic Code Mutation) <a class="header-anchor" href="#step-4-원자적-diff-패치-적용-atomic-code-mutation" aria-label="Permalink to “Step 4: 원자적 Diff 패치 적용 (Atomic Code Mutation)”">​</a></h3><ul><li><code>AtomicDiffPatchEngine</code>을 사용하여 지정된 <code>focusFiles</code>에 대해서만 변경분(Diff)을 라인 단위로 정밀하게 주입합니다.</li><li>기존 파일 전체를 덮어쓰지 않고 변경 블록만을 교체하므로 기존 주석 및 코딩 컨벤션의 훼손을 최소화합니다.</li></ul><hr><h2 id="_3-컴파일러-에러-역피드백-기반-빌드-자가치유-루프" tabindex="-1">3. 컴파일러 에러 역피드백 기반 빌드 자가치유 루프 <a class="header-anchor" href="#_3-컴파일러-에러-역피드백-기반-빌드-자가치유-루프" aria-label="Permalink to “3. 컴파일러 에러 역피드백 기반 빌드 자가치유 루프”">​</a></h2><p>패치가 적용된 직후, 시스템은 격리된 샌드박스 환경에서 실제 컴파일러(<code>javac</code>, <code>mvn test-compile</code>)와 테스트 러너를 실행하여 빌드 아티팩트를 실측 검증합니다.</p><ol><li><strong>오류 추적 및 컨텍스트 재합성</strong>: <ul><li>빌드 실패 발생 시, 컴파일러가 출력한 정확한 오류 메시지, 소스 파일명, 라인 번호, 심볼 미인식(Cannot find symbol) 등의 표준 에러 출력을 추출합니다.</li></ul></li><li><strong>에이전트 역피드백 (<code>autoRepairCode</code>)</strong>: <ul><li>추출된 오류 로그와 실패 지점 소스코드를 에이전트의 자가치유 모듈로 재주입합니다.</li><li>에이전트는 누락된 import 구문 추가, 메서드 시그니처 정합성 조정, 타입 캐스팅 오류 수정 등 컴파일 통과를 위한 최소 변경 패치를 다시 합성합니다.</li></ul></li><li><strong>반복 임계치 및 안전 종료</strong>: <ul><li>자가치유 루프는 최대 3회에서 5회 이내로 제한됩니다.</li><li>모든 컴파일 및 단위 테스트를 완전히 통과한 경우에만 유효한 PR(Pull Request)을 생성하며, 임계치 초과 시에는 작업 내용을 롤백하고 관리자에게 원인 분석 리포트를 전달합니다.</li></ul></li></ol><hr><h2 id="_4-선행기술-대비-정량적-차별성" tabindex="-1">4. 선행기술 대비 정량적 차별성 <a class="header-anchor" href="#_4-선행기술-대비-정량적-차별성" aria-label="Permalink to “4. 선행기술 대비 정량적 차별성”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">비교 항목</th><th style="text-align:left;">일반 AI 코딩 어시스턴트</th><th style="text-align:left;">정적 템플릿 코드 생성기</th><th style="text-align:left;">본 특허 시스템 (07호)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>코드 생성 방식</strong></td><td style="text-align:left;">단일 프롬프트 일괄 생성</td><td style="text-align:left;">고정된 스캐폴딩 템플릿</td><td style="text-align:left;"><strong>4단계 위저드 점진적 상세화</strong></td></tr><tr><td style="text-align:left;"><strong>문맥 환각 방지</strong></td><td style="text-align:left;">프롬프트 길이에 의존하여 취약</td><td style="text-align:left;">문맥 반영 불가</td><td style="text-align:left;"><strong>코드베이스 실측 및 focusFiles 격리</strong></td></tr><tr><td style="text-align:left;"><strong>컴파일 검증</strong></td><td style="text-align:left;">미제공 (인간 개발자가 확인)</td><td style="text-align:left;">컴파일은 되나 비즈니스 로직 부재</td><td style="text-align:left;"><strong>실제 컴파일러 연동 자동 검증</strong></td></tr><tr><td style="text-align:left;"><strong>빌드 오류 수복</strong></td><td style="text-align:left;">지원하지 않음</td><td style="text-align:left;">템플릿 수정 필요</td><td style="text-align:left;"><strong>컴파일러 에러 역피드백 자가치유</strong></td></tr></tbody></table><hr><h2 id="_5-실측-성능-및-코드베이스-구현-증적" tabindex="-1">5. 실측 성능 및 코드베이스 구현 증적 <a class="header-anchor" href="#_5-실측-성능-및-코드베이스-구현-증적" aria-label="Permalink to “5. 실측 성능 및 코드베이스 구현 증적”">​</a></h2><p>사내 마이크로서비스 백엔드 신규 기능 구현 150건 대상 실측 결과입니다:</p><ul><li><strong>1차 패치 후 빌드 통과율</strong>: 4단계 위저드 적용 시 82.6% 달성.</li><li><strong>자가치유 루프 통과율</strong>: 1차 빌드 실패 건 중 3회 이내 <code>autoRepairCode</code> 루프를 거쳐 최종 빌드 통과율 <strong>96.8%</strong> 기록.</li><li><strong>가짜 정상 코드 유입 차단</strong>: Zero-Mock 테스트 하네스와 결합하여 미구현 메서드 커밋 <strong>0건 유지</strong>.</li></ul><h3 id="코드베이스-구현-위치-grounding" tabindex="-1">코드베이스 구현 위치 (Grounding) <a class="header-anchor" href="#코드베이스-구현-위치-grounding" aria-label="Permalink to “코드베이스 구현 위치 (Grounding)”">​</a></h3><ul><li><code>sync-module-deploy/src/main/java/com/empasy/sync/deploy/engine/AtomicDiffPatchEngine.java</code>: 원자적 패치 주입기</li><li><code>sync-boot/Server/src/main/java/com/empasy/sync/boot/generator/FourStageWizardService.java</code>: 4단계 명세 위저드 엔진</li><li><code>sync-verse/Server/src/main/java/com/empasy/sync/verse/controller/SelfHealingRunbookController.java</code>: 빌드 검증 및 자가치유 오케스트레이터</li></ul>',24))])}const m=o(B,[["render",C]]);export{D as __pageData,m as default};
